"""Calendar analyzer — detects changes between calendar snapshots.

Compares the current events.json against the last committed version
to identify new, cancelled, moved, and conflicting events.
"""

import json
import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from pathlib import Path

from personal_assistant.state_repo import (
    DEFAULT_STATE_PATH,
    get_file_at_last_commit,
)
from personal_assistant.models import CalendarEvent

logger = logging.getLogger(__name__)


class ChangeType(str, Enum):
    NEW = "new"
    CANCELLED = "cancelled"
    TIME_CHANGED = "time_changed"
    ATTENDEES_CHANGED = "attendees_changed"


@dataclass
class CalendarChange:
    """A single detected change in the calendar."""

    change_type: ChangeType
    event: CalendarEvent
    previous_event: CalendarEvent | None = None
    detail: str = ""


@dataclass
class Conflict:
    """Two events that overlap in time."""

    event_a: CalendarEvent
    event_b: CalendarEvent
    overlap_description: str = ""


@dataclass
class CalendarAnalysis:
    """Complete analysis result for one calendar."""

    calendar_file: str
    changes: list[CalendarChange] = field(default_factory=list)
    conflicts: list[Conflict] = field(default_factory=list)
    current_event_count: int = 0
    previous_event_count: int = 0


def analyze_calendar(
    calendar_file: str = "calendar/events.json",
    *,
    repo_path: Path = DEFAULT_STATE_PATH,
) -> CalendarAnalysis:
    """Analyze changes in a calendar events file.

    Compares the current file on disk against the last committed version.
    """
    current_events = _load_current_events(calendar_file, repo_path=repo_path)
    previous_events = _load_previous_events(calendar_file, repo_path=repo_path)

    analysis = CalendarAnalysis(
        calendar_file=calendar_file,
        current_event_count=len(current_events),
        previous_event_count=len(previous_events),
    )

    current_by_id = {e["id"]: e for e in current_events}
    previous_by_id = {e["id"]: e for e in previous_events}

    # New events (skip if user already declined)
    for event_id, event in current_by_id.items():
        if event_id not in previous_by_id and not _user_declined(event):
            analysis.changes.append(
                CalendarChange(
                    change_type=ChangeType.NEW,
                    event=event,
                    detail=f"New: {event['summary']} at {event['start']}",
                )
            )

    # Cancelled events (skip if user had declined)
    for event_id, event in previous_by_id.items():
        if event_id not in current_by_id and not _user_declined(event):
            analysis.changes.append(
                CalendarChange(
                    change_type=ChangeType.CANCELLED,
                    event=event,
                    detail=(f"Cancelled: {event['summary']} " f"at {event['start']}"),
                )
            )

    # Modified events (skip if user declined in current version)
    for event_id in current_by_id.keys() & previous_by_id.keys():
        current = current_by_id[event_id]
        previous = previous_by_id[event_id]

        if _user_declined(current):
            continue

        if current["start"] != previous["start"] or current["end"] != previous["end"]:
            analysis.changes.append(
                CalendarChange(
                    change_type=ChangeType.TIME_CHANGED,
                    event=current,
                    previous_event=previous,
                    detail=(
                        f"Moved: {current['summary']} "
                        f"{previous['start']} -> {current['start']}"
                    ),
                )
            )

        current_attendees = {a["email"] for a in current.get("attendees", [])}
        previous_attendees = {a["email"] for a in previous.get("attendees", [])}
        if current_attendees != previous_attendees:
            added = current_attendees - previous_attendees
            removed = previous_attendees - current_attendees
            parts = []
            if added:
                parts.append(f"added: {', '.join(sorted(added))}")
            if removed:
                parts.append(f"removed: {', '.join(sorted(removed))}")
            analysis.changes.append(
                CalendarChange(
                    change_type=ChangeType.ATTENDEES_CHANGED,
                    event=current,
                    previous_event=previous,
                    detail=(
                        f"Attendees changed on {current['summary']}: "
                        + "; ".join(parts)
                    ),
                )
            )

    # Conflict detection
    timed_events = [e for e in current_events if not e.get("all_day", False)]
    analysis.conflicts = _detect_conflicts(timed_events)

    return analysis


def analyze_all_calendars(
    *,
    repo_path: Path = DEFAULT_STATE_PATH,
) -> list[CalendarAnalysis]:
    """Analyze all calendar files in the state repo."""
    calendar_dir = repo_path / "calendar"
    if not calendar_dir.exists():
        return []

    analyses = []
    for json_file in sorted(calendar_dir.glob("events*.json")):
        rel_path = str(json_file.relative_to(repo_path))
        analyses.append(analyze_calendar(rel_path, repo_path=repo_path))
    return analyses


def format_analysis(analysis: CalendarAnalysis) -> str:
    """Format a calendar analysis as a human-readable report."""
    lines: list[str] = []
    lines.append(f"## Calendar: {analysis.calendar_file}")
    lines.append(
        f"Events: {analysis.previous_event_count} -> " f"{analysis.current_event_count}"
    )

    if not analysis.changes and not analysis.conflicts:
        lines.append("No changes detected.")
        return "\n".join(lines)

    if analysis.changes:
        lines.append("")
        lines.append("### Changes")
        for change in analysis.changes:
            lines.append(f"- **{change.change_type}**: {change.detail}")

    if analysis.conflicts:
        lines.append("")
        lines.append("### Conflicts")
        for conflict in analysis.conflicts:
            lines.append(
                f"- {conflict.event_a['summary']} "
                f"({conflict.event_a['start']}) "
                f"overlaps {conflict.event_b['summary']} "
                f"({conflict.event_b['start']})"
            )
            if conflict.overlap_description:
                lines.append(f"  {conflict.overlap_description}")

    return "\n".join(lines)


def _load_current_events(
    calendar_file: str,
    *,
    repo_path: Path,
) -> list[CalendarEvent]:
    """Load current events from the state repo on disk."""
    filepath = repo_path / calendar_file
    if not filepath.exists():
        return []
    try:
        with open(filepath) as f:
            data = json.load(f)
        if isinstance(data, list):
            return data
        return []
    except (json.JSONDecodeError, OSError) as exc:
        logger.warning("Failed to load %s: %s", filepath, exc)
        return []


def _load_previous_events(
    calendar_file: str,
    *,
    repo_path: Path,
) -> list[CalendarEvent]:
    """Load events from the last committed version."""
    content = get_file_at_last_commit(calendar_file, repo_path=repo_path)
    if content is None:
        return []
    try:
        data = json.loads(content)
        if isinstance(data, list):
            return data
        return []
    except json.JSONDecodeError as exc:
        logger.warning("Failed to parse committed %s: %s", calendar_file, exc)
        return []


def _parse_event_time(time_str: str) -> datetime | None:
    """Parse an event time string to a datetime.

    Handles both ISO datetime ("2026-03-30T08:00:00-04:00")
    and date-only ("2026-03-30") formats.
    """
    if not time_str:
        return None
    try:
        return datetime.fromisoformat(time_str)
    except ValueError:
        return None


def _user_declined(event: CalendarEvent) -> bool:
    """Check if the user declined this event."""
    user_attendee = next(
        (a for a in event.get("attendees", []) if a.get("self")),
        None,
    )
    return (
        user_attendee is not None and user_attendee.get("response_status") == "declined"
    )


def _detect_conflicts(events: list[CalendarEvent]) -> list[Conflict]:
    """Find overlapping timed events.

    Only checks events the user is attending (not declined).
    """
    attending = []
    for event in events:
        if event.get("status") == "cancelled":
            continue
        if _user_declined(event):
            continue
        attending.append(event)

    conflicts: list[Conflict] = []
    for i, event_a in enumerate(attending):
        start_a = _parse_event_time(event_a["start"])
        end_a = _parse_event_time(event_a["end"])
        if not start_a or not end_a:
            continue

        # Normalize to UTC for comparison
        start_a_utc = start_a.astimezone(timezone.utc)
        end_a_utc = end_a.astimezone(timezone.utc)

        for event_b in attending[i + 1 :]:
            start_b = _parse_event_time(event_b["start"])
            end_b = _parse_event_time(event_b["end"])
            if not start_b or not end_b:
                continue

            # Normalize to UTC for comparison
            start_b_utc = start_b.astimezone(timezone.utc)
            end_b_utc = end_b.astimezone(timezone.utc)

            # Overlap: A starts before B ends AND B starts before A ends
            if start_a_utc < end_b_utc and start_b_utc < end_a_utc:
                conflicts.append(
                    Conflict(
                        event_a=event_a,
                        event_b=event_b,
                    )
                )

    return conflicts
